package com.djibtout.backend.controller;import com.djibtout.backend.entity.HomeSection;import com.djibtout.backend.repository.HomeSectionRepository;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/home-sections") public class AdminHomeSectionController{private final HomeSectionRepository repository;public AdminHomeSectionController(HomeSectionRepository r){repository=r;}@GetMapping public List<HomeSection> list(){return repository.findAll().stream().sorted(Comparator.comparingInt(HomeSection::getDisplayOrder)).toList();}@PutMapping("/{id}") public ResponseEntity<HomeSection> update(@PathVariable Long id,@Valid @RequestBody HomeSection input){return repository.findById(id).map(section->{section.setKey(input.getKey());section.setTitle(input.getTitle());section.setSubtitle(input.getSubtitle());section.setActive(input.isActive());section.setDisplayOrder(input.getDisplayOrder());section.setCategory(input.getCategory());section.setMaxItems(input.getMaxItems());return ResponseEntity.ok(repository.save(section));}).orElse(ResponseEntity.notFound().build());}}
